  function interpolate(a, b, t) {
    a = unwrap(a); b = unwrap(b);
    if (typeof a === 'number' && typeof b === 'number') return t <= 0 ? a : t >= 1 ? b : a*(1-t)+b*t;
    const ca = color(a), cb = color(b);
    if (ca && cb) {
