  }
  function easing(spec, t) {
    const type = Array.isArray(spec) ? 'cubicBezier' : typeof spec === 'string' ? spec : (spec || {}).type || 'linear';
    if (type === 'step' || type === 'discrete') return t < 1 ? 0 : 1;
    if (type === 'linear') return t;
